  customer_email = VALUES(customer_email), customer_name = VALUES(customer_name), customer_phone = VALUES(customer_phone),
  order_status = VALUES(order_status), payment_status = VALUES(payment_status), fulfillment_status = VALUES(fulfillment_status),
  currency = VALUES(currency), subtotal_amount = VALUES(subtotal_amount), total_amount = VALUES(total_amount),
  refunded_amount = VALUES(refunded_amount), order_items = VALUES(order_items),
  item_count = VALUES(item_count), total_quantity = VALUES(total_quantity),
  tracking_number = VALUES(tracking_number), tracking_carrier = VALUES(tracking_carrier),
