  note = VALUES(note), sync_source = VALUES(sync_source), is_deleted = VALUES(is_deleted);

-- 按真实订单回填客户消费汇总（total_orders / total_spent / avg / last_order_at / total_conversations）
UPDATE customer c
SET c.total_orders = (
        SELECT COUNT(*) FROM order_info o
        WHERE o.tenant_id = c.tenant_id AND o.customer_id = c.id
          AND o.is_deleted = 0 AND o.order_status <> 'cancelled'),
    c.total_spent = (
        SELECT COALESCE(SUM(o.total_amount - o.refunded_amount), 0) FROM order_info o
        WHERE o.tenant_id = c.tenant_id AND o.customer_id = c.id
          AND o.is_deleted = 0 AND o.order_status <> 'cancelled'),
    c.avg_order_value = (
        SELECT COALESCE(AVG(o.total_amount - o.refunded_amount), 0) FROM order_info o
        WHERE o.tenant_id = c.tenant_id AND o.customer_id = c.id
          AND o.is_deleted = 0 AND o.order_status <> 'cancelled'),
    c.last_order_at = (
        SELECT MAX(o.placed_at) FROM order_info o
        WHERE o.tenant_id = c.tenant_id AND o.customer_id = c.id AND o.is_deleted = 0),
    c.total_conversations = (
        SELECT COUNT(*) FROM conversation v
        WHERE v.tenant_id = c.tenant_id AND v.customer_id = c.id AND v.is_deleted = 0)
WHERE c.tenant_id IN (1001, 1002) AND c.id BETWEEN 2001 AND 2016;
